   "source": "2016年423联考《行测》题 · 第7题",
   "question": "“本质性诗人”大致有两种出路：其一是像陶渊明那样从急流中退出，在山水间________自己的灵魂。尽管现实中并不存在桃花源，但________在内心一隅还是可能的。其二是原地不动，像屈原那样与污浊的世界对抗。这注定了他与世界的_______是持续的、难以调和的。\n依次填入画横线部分最恰当的一项是：",
