   "module": "言语理解与表达",
   "source": "2016年423联考《行测》题 · 第17题",
   "question": "爱的价值，由被爱的方式决定。爱不是给予而是被接受；被爱不是接受，被爱才是给予。没有被接受，就不是爱，不管你付出多少。许多人都单纯地、片面地认为，爱就是给予，只要真心付出，毫无保留地付出，就证明了爱——其实这是错的。真正的爱，必须被接受，否则就只能算是示好，想获得青睐的举动。如果给予就是爱，岂不天下大乱，岂不人人假爱之名，妄行强迫威逼之实。\n 最适合做本段文字标题的是：",
   "options": [
    "A. 爱是被接受",
    "B. 爱的价值",
    "C. 爱是被爱",
    "D. 爱是接受"
   ],
