   "analysis": "文段首先引入话题——爱的价值是由“被爱的方式”来决定的。然后进行解释说明，爱不是给予而是被接受，并具体论述什么样的方式才是真正的“爱”，即“被接受”的爱才是真爱，故文段意在强调爱是被接受，对应A项。\nB项“价值”、C项“被爱”、D项“接受”均和“被接受”语义不符，排除。\n故正确答案为A。\n【文段出处】博泰典藏网 《家庭心理学》",
   "exam": "tianjin",
   "year": 2016
