   "question": "从政治经济到日常生活，从全球化到地区的复兴，从实用技术到话语表达所面对的诸多难题乃至危机，都与空间这一因素密切相关。这是以地震海啸灾难、边界武装冲突、房地产业崩盘、道路拥堵以及空间竞争日趋激烈等多种形式表现出来的。\n这段文字意在说明：",
