   "source": "2016年423联考《行测》题 · 第27题",
   "question": "我国古代对于公文的保密最早可以追溯到夏朝。据史书记载，太史令将“图法”（即国家的重要典志、档案）“宫藏”；商朝时，设立了守藏史这一官职，专门负责保管政府公务文书和典册；周朝继承了商朝的传统，将文书正本收藏于天府——我国历史上最早的中央档案机构。到了秦朝时，在文书上玺印封缄，在传递过程中使用“封泥”已是普遍的一种做法。到了东汉时期，办公文件保密用的“封泥”竟然成为把守关隘的比喻词。《后汉书·隗嚣传》记载：“（王）元请以一丸泥为大王东封函谷关，此万世一时也。”说明守关如封泥，应小心翼翼，不得有一丝疏漏。\n这段文字主要介绍的是：",
