   "source": "2016年423联考《行测》题 · 第29题",
   "question": "①最早的单质碘便是法国人从海藻中发现的，海藻也是最早的碘生产原料 \n②我国大部分地区都缺碘，碘不足可能会引起甲状腺肿病和地方性克汀病 \n③近年来，随着人们对食品纯天然的追求，海藻碘盐越来越受到欢迎 \n④碘在自然界中比较稀少，但是海洋中的藻类却有较高的含碘量 \n⑤碘是人体必需的微量元素之一，有“智力元素”之称 \n⑥因此从1995年起，我国开始实施食盐强制加碘 \n将以上六个句子重新排列，语序正确的是：（  ）",
   "options": [
    "A. ②⑤⑥③①④",
    "B. ③①④⑤②⑥",
    "C. ④③①⑤⑥②",
    "D. ⑤②⑥④①③"
   ],
   "answer": "D",
   "analysis": "对比选项，确定首句。②句介绍我国大部分地区缺碘的情况与危害，③句介绍海藻碘盐受到欢迎，④句介绍碘在自然界中的分布情况，⑤句给碘进行下定义，引出碘的话题，按照逻辑顺序可知，应先引出碘的话题，再进行具体介绍，故⑤句更适合做首句，A、B、C三项排除，锁定D项。\n验证D项。⑤句给碘进行下定义，引出碘的话题，②句介绍我国大部分地区缺碘的情况与危害，⑥句提出对策，实施食盐强制加碘。随后④①③详细介绍通过提取海藻当中的碘，可实现海藻碘盐的制作，逻辑通顺，D项当选。\n故正确答案为D。\n【文段出处】《这些东西里都有海洋的身影》",
   "exam": "tianjin",
   "year": 2016
