   "source": "2016年423联考《行测》题 · 第32题",
   "question": "现代化学与炼金（炼丹）的相同点是从分子层面创造新事物，至于创造新元素其实是核物理学家的任务，由他们拿一些回旋加速机把新元素轰出来然后再填到元素周期表中作为化学家的胜利果实。古典炼金术实际上已经有了元素、原子这样的理念，但并不具备理性思维，例如中世纪的欧洲人认为，轻、重、干、湿是基本的物理性质，干而轻的是火，干而重的是土，湿而轻的是气，湿而重的是水，因此，任何物质均是由水、火、土、气这四种基本元素按不同比例合成的结果，这与目前可知世界的观念显然不同，而同时期其他文明中对物质本质的认识同样也是介于神秘与理性之间。\n接下来最可能讲的是：",
   "options": [
    "A. 现代化学理性思维的起点",
    "B. 物理学家如何创造新元素",
    "C. 古典炼金术对欧洲文明的影响",
    "D. 可知世界中关于元素的各种观念"
   ],
   "answer": "A",
   "analysis": "本题为接语选择题，需通读全文把握核心话题。文段先对比现代化学与炼金（炼丹），指出古典炼金术不具备理性思维，且当时文明对物质本质的认识介于神秘与理性之间。由此可推断，接下来可能围绕现代化学如何具备理性思维展开，即现代化学理性思维的起点，对应A项。\nC项，文段尾句核心话题是“现代化学的理性思维”，而非“欧洲文明”，话题不一致，排除；\nB项，“物理学家如何创造新元素”、D项，“可知世界中关于元素的各种观念”，均为上文已经论述过的内容，后文不会再讲，排除。\n故正确答案为A。\n【文段出处】《中国人学化学以及疯狂的造字》",
   "exam": "tianjin",
   "year": 2016
