   "question": "痴呆是一种以认知功能缺损为核心症状的获得性智能损害综合征，其智能损害的程度足以干扰社会或职业功能，是慢性进展性的疾病，损害的范围涉及记忆、行为、人格、判断、注意力、视空间技能、语言、逻辑推理等多种高级神经功能。据统计，痴呆已成为仅次于心血管疾病、癌症和脑猝的第四大杀手，严重威胁老年人身体健康和生活质量。年龄，是老年性痴呆的重要危险因素，一般认为，60岁以上的人群中，每增加5岁，痴呆的患病率将增加1倍。随着老年人口的不断增加，老年痴呆将成为我国一个严重的公共卫生问题。\n根据这段文字，以下说法正确的是：",
