   "question": "花儿为什么这样红？最后要归功于人工选择。自然选择进程缓慢，需要经过很长时间才能显示它的作用，人工选择大大加快了它的进程，能够在较短的时间内取得显著成果。人工栽培的历史仅二三百年，却已有上千种形状、颜色不同的品种。\n这段文字主要支持了这样一个观点，即：",
