   "analysis": "第一空，所填词语表示柔性材料对于结构的作用，强调可以变化的，结构是不固定的，C 项“灵活”指不固定，符合文意，当选。A 项“灵便”侧重强调方便，文中并无使用方便之义，且与“结构”搭配不当，排除。B 项“活动”强调可运动状态，与文段“柔性”所体现出来的柔韧特性不符，排除。D 项“灵敏”即敏感、灵敏度，强调反应快，与“结构”搭配不当，排除。\n第二空，代入验证，所填词语表示刚性材料对于结构的作用，“稳定性”为常见搭配，和“刚性”形成对应，C 项当选。\n故正确答案为 C。\n【文段出处】《DNA纳米技术与生物医学研究》",
   "exam": "tianjin",
   "year": 2017
