   "question": "20世纪90年代，有人        传统书信将被新兴的通信方式取代。然而我们惊奇地发现，传统的纸质书信依然健康发展，与电子通信方式            ，在当下生活中发挥着重要的作用。\n依次填入画横线部分最恰当的一项是：",
