   "source": "2017年422联考《行测》题 · 第9题",
   "question": "2016年中央电视台春节联欢晚会表演的节目《华阴老腔一声喊》，吸纳了非物质文化遗产元素。它源于生活，既接地气又创新出彩，              。它的成功，关键在于华阴老腔的魅力，传统音乐元素没有随着岁月流逝而失去光泽，它在现代音乐的包装下还能              。\n依次填入画横线部分最恰当的一项是：",
