   "source": "2017年422联考《行测》题 · 第12题",
   "question": "语言本身就是人类文化长期            的智慧结晶。一切人类创造的思想文化成果都需要通过语言来深度表达和精彩            ，如果将文化视为人类精神或思维自觉            的形形色色的神奇“痕迹”，那么，语言就是这种“痕迹”中最鲜活、最深邃和最久远的核心部分。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 演进  描述  保存",
    "B. 培育  演绎  留传",
    "C. 发展  诠释  存留",
    "D. 积淀  阐释  遗留"
   ],
   "answer": "D",
