   "source": "2017年422联考《行测》题 · 第13题",
   "question": "近日，国际著名学术杂志《自然—材料》（Nature Materials）刊登了铁基高温超导材料研究领域的一项重要       ——新型一维拓扑边界态的发现。拓扑超导体最              的应用就是高能量子计算机，它能在计算中发现错误，一旦出错就会在信息      过程中产生抵抗。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 进程 鼓舞人心 存储",
    "B. 进展 激动人心 处理",
    "C. 成就 令人振奋 加工",
    "D. 成果 引以为傲 传输"
   ],
