   "source": "2017年422联考《行测》题 · 第14题",
   "question": "责任心，是创业者               的品质。经常在生活中磨炼的人一定碰到过困难与荆棘、遇到过挑战与挫折、感受过真情与冷暖、领悟过付出与回报，久而久之，人的内心变得坚强，说话做事更有担当，“责任”二字通过潜移默化的行为训练         创业者的血液里，变成人的气节与气质，形成了独有的               。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 千金难求  植入  感召力",
    "B. 不可多得  渗入  亲和力",
    "C. 难能可贵  融入  竞争力",
    "D. 绝无仅有  介入  创新力"
   ],
   "answer": "C",
