   "module": "言语理解与表达",
   "source": "2017年422联考《行测》题 · 第15题",
   "question": "实现不同产业发展模式的升级，关键是突破核心技术、掌握知识产权，这就需要企业由过去的重投资转向重创新，由注重规模       转向注重行业竞争力的提升。如果不能由低端制造向高生产率的设计、研发、品牌、营销、产品链管理等环节      ，企业就会错过产品升级的机遇，更      创新活跃期所带来的重大发展机遇。\n依次填入画横线部分最恰当的一项是：",
