   "source": "2017年422联考《行测》题 · 第17题",
   "question": "我国各地的雾霾，从总的方面来说是各种来源污染排放物经过一系列的化学和物理过程的产物，这里既有一次排放，还有二次化学转化和物理过程。从南到北情况十分复杂，当下的普遍情况既不同于当年伦敦的情况，也不同于洛杉矶的情况。曾有学者讲北京的情况属于“伦敦型”和“洛杉矶型”的复合型，实际上事情绝非是一个“复合型”可以概括。还让人担心的是：眼下从上到下，各省各地都认为燃煤是问题的根子，似乎实现城市燃气化以后，问题就可以大大解决了，其实我们的一次排放物或者说二次过程的产生物质决不只是一个二氧化硫，或者说再加上一个氮氧化合物那么简单。\n对这段文字概括最恰当的是：",
   "options": [
    "A. 雾霾形成的主要特点",
    "B. 雾霾形成的原因复杂",
    "C. 雾霾类型具有多样性",
    "D. 雾霾危害具有普遍性"
   ],
