   "source": "2017年422联考《行测》题 · 第19题",
   "question": "除了人类以外的灵长类动物都学不会发声，没有模仿所听到声音的能力——这种能力对于说话而言必不可少。但近日，研究者表示，灵长类动物能以近乎交谈的方式互相呼喊，因为它们会等待呼喊结束再发声。如果这种技能是后天习得的，那么它更接近人类的类似技能，因为婴儿是在咿呀学语的过程中学会这种技能的。这一发现或可帮助我们                                 。\n填入画横线部分最恰当的一项是：",
