   "source": "2017年422联考《行测》题 · 第25题",
   "question": "有“明清古建筑博物馆”之称的三坊七巷街区，有人将其比喻为鱼骨与鱼刺，有人则形容为菩提树叶，或直呼为“非”字形。笔者觉得，它倒更像一片优美的棕榈树枝叶，南后街似叶片的主脉，向西伸出的三条支脉为三坊，向东生出的七条细脉是七巷。由北向南的三坊依次为衣锦坊、光禄坊、文儒坊，七巷的顺序依次为杨桥巷、郎官巷、塔巷、黄巷、安民巷、官巷和吉庇巷。\n对这段文字的内容概括最恰当的一项是：",
