   "source": "2017年422联考《行测》题 · 第29题",
   "question": "中国的FAST（500米口径球面射电望远镜）主体的落成为何引起海内外的热烈关注？原因有三。一是看得远。作为目前口径最大的射电望远镜，FAST在理论上可以接收到137亿光年以外的电磁信号。二是很灵活。FAST的索网结构可以随着天体移动变化，极大提升观测效率。三是高精度。FAST射电望远镜的结构，处处都是毫米级精度要求；用来编织索网的手臂般粗细的钢缆，加工精度都被控制在1毫米以内；最终的天线精度是3个毫米，小面板的制造精度是1.5个毫米。这一切意味着我们将能倾听来自宇宙更深处的声音，观测宇宙更隐蔽的奥秘。\n这段文字最适合的标题是：",
   "options": [
    "A. 海内外热烈关注中国的FAST",
    "B. 走近中国FAST走进宇宙深处",
    "C. 中国的FAST有三大过人之处",
    "D. 一起倾听来自宇宙深处的声音"
   ],
   "answer": "B",
   "analysis": "文段开篇提出“中国的FAST为何引起海内外关注”的问题，接着从三个方面分析原因，尾句通过“这一切”总结前文，强调中国FAST意味着“我们将能倾听来自宇宙更深处的声音，观测宇宙更隐蔽的奥秘”，故文段重在强调“FAST”对于“宇宙”的作用，对应B项。\nA项对应首句提出问题的表述，非重点，排除；C项“三大过人之处”非重点，且没有体现出对“宇宙”的作用，排除；D项只提到“宇宙”，没有提到“FAST”这一核心话题，偏离文段的中心，排除。\n故正确答案为B。\n【文段出处】《中国FAST将睁开天眼 射电望远镜带你探索宇宙奥秘》",
   "exam": "tianjin",
   "year": 2017
