   "source": "2017年422联考《行测》题 · 第30题",
   "question": "在读屏时代，从倡导多读多写汉字的角度，“汉字听写”无疑是一件好事。但是一旦过度，好事也会变成坏事。比如，比赛偏重冷僻字词，参赛小选手们只能强化记忆，在比赛中展示了“中国式教育”。就连汉字拼音之父周有光先生也认为，现在把通用汉字增加到8000多个，这个数量实在有点太多了。联想到近几年一直没有停歇过的汉字繁简之争以及中高考改革方案的推出，我们不难发现，大家对汉语言文字的关注在日渐深入，民众的母语水平和学习母语的积极性在不断提高。\n从这段文字，可以看出作者的态度是：",
   "options": [
    "A. 新时期的汉字听写比赛应该适度适当导向正确",
    "B. 读屏时代的汉字听写加快语言教育改革的步伐",
    "C. 汉字听写数量过多会引发民众提笔忘字的忧虑",
    "D. 中国式教育与强化记忆是语文教育的必要手段"
   ],
   "answer": "A",
   "analysis": "文段首先指出在读屏时代“汉字听写”是一件好事，接下来用“但是”进行转折，指出“一旦过度，好事也会变成坏事”，从反面提出对策，强调应该适度。随后用“比如”举例说明，之后又通过周有光先生的观点、汉字繁简之争和中高考改革方案对前文观点进行再次论证。因此文段强调的重点是“汉字听写”要适度，对应A项。\nB、C两项：B项“加快语言教育改革的步伐”、C项“引发民众提笔忘字的忧虑”均无中生有，排除。\nD项：与作者的观点相悖，排除。\n故正确答案为A。\n【文段出处】《汉字听写，莫沦为“奥赛”》",
   "exam": "tianjin",
   "year": 2017
