   "question": "目前人造关节所用的材料不外乎金属和塑料两大类。由于人体内钾、钠、氯等化学物质可能使金属材料腐蚀生锈，塑料老化，所以选用的金属和塑料的化学性质必须高度稳定。\n这段话的主要观点是（    ）。",
