   "source": "2017年天津市选调生选拔考试 综合知识试卷 · 第18题",
   "question": "人的世界观的形成有一定的轨迹，人的一切言行总是一定“轨迹”的体现，资产阶级的唯我主义的形成是圆内半径运行轨迹的结果。这个“圆”的圆心就是“我”，“半径”则是个人的利害得失。\n对文字中画横线句子理解正确的一项是（    ）。",
