   "source": "2017年天津滨海新区公务员考试《行测》题 · 第8题",
   "question": "欧洲科学家历时两年____230万欧元，开发出了一种“智能安全摄像头”。这种“智能安全摄像头”能够利用电脑，以某种运算法则分析在公共场所拍下的录像画面，查找可疑____，从中发现潜在的安全威胁。\n下列选项中，最适合填入横线的是：",
