   "answer": "A",
   "analysis": "本题可从第二空入手，根据“希腊专业的史学著述仅限当代史范畴……”可知，横线处表达中国的史学传统与古希腊在理论上是不一样的。“大异其趣”指表现得大不相同、差异很大，符合文意。“剑走偏锋”指不走常规，找一些新的、不同以往的办法来解决问题，以求出奇制胜，与文意不符，排除B、C两项。\n第一空，根据转折词“却”可知，横线处表达中国的史学传统与古希腊地位相当之意，A项“双峰对峙”指两山相对耸立，不分高下，进行对抗、抗衡，符合文意。D项“遥相对峙”指距离很远，相对耸立，“遥相”不能用来形容史学传统与古希腊的地位相当，排除。\n故正确答案为A。\n【文段出处】《历史真的只有那么点事儿》",
