   "question": "针对网上传言“驾车用蓝牙耳机接电话要被扣分”，有交警表示此为误传。目前新交法规定了开车中不能拨打手持电话，对于使用蓝牙耳机或车载蓝牙没有明确规定，而且佩戴蓝牙设备并不能确定其是否在打电话，所以查处有一定难度。不过使用耳机接打电话，驾驶人的注意力仍然会被分散，所以并不提倡驾车时使用。下列选项中，对上文理解错误的一项是：",
