   "question": "一线城市的高房价以及90后年轻人对生活品质的追求，催生了租赁公寓的兴起。租赁公寓迎合了年轻人的消费观念，租房由过去的不得已转变成享受生活的一种方式。据调查，虽然拥有自己的住房仍是90后的刚性需求，但他们当中只有img/formula-2f29ab37e5278826.webp愿意为了买房而降低生活质量；另有img/formula-29477a3ea0f859e7.webp的90后不愿意买房，因为房贷过于沉重会降低生活质量。由此观之，这些更看重个人价值的90后，可能成为“不买房一代”。\n这段文字意在强调：",
