   "question": "在中国城镇化进程中，传统戏曲面临着前所未有的生态变化。民间职业演出积极地适应农村娱乐需要，或者重新恢复传统民俗演剧形式，借助节庆礼俗，发挥戏曲传统的礼乐教化职能；或者与时俱进，以时尚流行的艺术元素充实戏曲本体，衍生出新的戏剧娱乐形态。体制内职业剧团在传统与创新中进行艺术传承，或者深入农村、送戏下乡，仍然维持在基层农村的演出；或者放弃农村，寻求多元的创新方式，勉力维持城市市场，导致戏曲在农村文化生活中趋于弱势和边缘。\n这段文字意在说明：",
   "options": [
    "A. 戏曲艺术传承发展要寻求多元化和与时俱进",
    "B. 戏曲是传承和弘扬优秀传统文化的重要载体",
    "C. 政府要加大力度支持职业剧团在农村的演出",
    "D. 戏曲在农村的影响力出现了两极化发展趋势"
   ],
   "answer": "D",
   "analysis": "文段开篇介绍城镇化过程中传统戏曲面临生态变化，并从“民间职业演出”和“体制内职业剧团”两个不同的角度阐述了戏曲在农村中的发展状况，“民间职业演出”积极适应农村娱乐需要或者通过与时俱进衍生出新的戏剧娱乐形态体现其发展趋势良好，“体制内职业剧团”采取的方式使其在农村文化生活中处于弱势和边缘。故文段通过“民间职业演出”和“体制内职业剧团”发展状况进行对比，强调戏曲在农村中出现两极分化的趋势，对应D项。\nA项，“多元”对应文段尾句，由“寻求多元的创新方式，勉力维持城市市场，导致戏曲······趋于弱势和边缘”可知，寻求“多元”并不是合理的做法，排除；\nB项，文段强调的是戏曲面临的新变化，“戏曲是······重要载体”偏离文段核心话题，排除；\nC项，“政府要加大力度支持职业剧团”文段没有提及，无中生有，排除。\n故正确答案为D。 \n【文段出处】《美丽乡村：戏曲绽放异彩的广阔空间》",
   "exam": "tianjin",
   "year": 2018
