   "module": "言语理解与表达",
   "source": "2019年1月天津市定向招录选调生考试综合能力测试试卷 · 第2题",
   "question": "乐观地说，先不论孩子们写了什么，仅就这种想象的本身，就        着多彩的光芒：教育的成就、文学的繁荣、出版的敏锐。\n填入画横线部分最恰当的一项是：",
