   "question": "古史不是断片的杂记，便是顺接年月的纂录；自出机杼，创立规模，以驾驭去取各种史料的，从《史记》始。司马迁的确能够贯穿经传，整齐百家杂语，成一家言。他明白“整齐”的必要，并知道怎样去“整齐”：这实在是创作，是以述为作。他这样将自有文化以来的三千年间君臣士庶的行事，“合一炉而冶之”，却反映着秦汉大一统的局势。\n本文中“整齐”指的意思是：",
