   "question": "极光多姿多彩，变化万千，任何彩笔都很难绘出那在严寒的两极空气中嬉戏无常、变幻莫测的炫目之光。在自然界中还没有哪种现象能与之        。极光有时出现时间极短，犹如节日的焰火，在空中闪现一下就消失得无影无踪；有时却可以在苍穹之中        几个小时；有时像一条彩带，有时像一团火焰，有时像一张五光十色的巨大银幕，仿佛上映一场球幕电影，给人视觉上极美的享受。\n依次填入划横线部分最恰当的一项是：",
   "options": [
    "A. 匹敌  延宕",
    "B. 相较  迤逦",
    "C. 媲美  辉映",
    "D. 抗衡  映照"
   ],
