   "module": "言语理解与表达",
   "source": "2019年420联考《行测》题（天津卷） · 第15题",
   "question": "习近平主席在上海合作组织成员国元首理事会第十八次会议上的重要讲话，深刻分析了我们今天所共同面对的风险挑战：当今世界霸权主义和强权政治        存在；各种传统和非传统安全威胁不断        ；单边主义、贸易保护主义、逆全球化思潮不断有新的表现；文明冲突、文明优越等论调不时            。\n依次填入划横线部分最恰当的一项是：",
