   "source": "2020年天津市公务员考试《行测》试题 · 第3题",
   "question": "防控疫情，应该多一些“小题大做”的        意识。小题大做，不是无理取闹，更不是渲染紧张气氛，而是体现出对疫情的        ，以及对防控疫情的重视。\n依次填入划横线部分最恰当的一项是：",
