   "module": "言语理解与表达",
   "source": "2020年天津市公务员考试《行测》试题 · 第9题",
   "question": "研究需要            ，传播需要放下架子。中科院将物理公式和黑洞等天文现象艺术化设计后，做成了井盖涂鸦，颠覆了科学        的刻板印象，        其趣味性和人情味，推动了科学与艺术的结合，有利于科学传播以及科学氛围的形成。\n依次填入划横线部分最恰当的一项是:",
