   "source": "2020年天津市公务员考试《行测》试题 · 第21题",
   "question": "朊病毒是一种结构异常的蛋白，能迫使正常蛋白呈现相同的错误折叠形状并像传染病一样在组织中传播。这是继认识到细菌、病毒、支原体等微生物可以引发疾病后，人类又发现的另一种引发疾病的病原体。因此，如果想要成功开发有效的治疗方法，需要针对（靶向）有活性的朊病毒，而不是已经死亡的斑块和缠结物中的大量蛋白。\n从这段文字我们可以推出:",
   "options": [
    "A. 朊病毒的结构非常复杂",
    "B. 朊病毒比细菌危害更大",
    "C. 朊病毒能够引发疾病",
    "D. 朊病毒引发的疾病能够被有效治疗"
   ],
   "answer": "C",
   "analysis": "A项，根据“朊病毒是一种结构异常的蛋白”，只是强调其结构和其他的不一样，并未阐述结构复不复杂，偷换概念，排除；\nB项，文段只是论述朊病毒同细菌、病毒等微生物一样，可以引发疾病，并未涉及到朊病毒和细菌谁危害性更大的比较，无关对比，排除；\nC项，根据“这是继认识到细菌、病毒、支原体等微生物可以引发疾病后，人类又发现的另一种引发疾病的病原体”可知，表述正确，当选；\nD项，根据“如果想要成功开发有效的治疗方法”可知，文中只是论述一种有效治疗方法的假设情况，选项以肯定语气论述出来，偷换语气，故表述错误，排除。\n故正确答案为C。\n【文段出处】《谨慎看待老年性痴呆药物的历史性突破》",
   "exam": "tianjin",
   "year": 2020
