   "module": "言语理解与表达",
   "source": "2020年天津市公务员考试《行测》试题 · 第34题",
   "question": "①“适度距离”不单是居住空间上的物理距离，也是心理上的“代际距离”。\n②个性解放、知识快速更新和年轻一代的经济独立不断冲击着传统家长权威。\n③当年轻人与父辈的价值观念和行为方式难以快速趋同时，保持适度距离是确保良性代际互动的前提。\n④在社会转型进程中，中国的家庭结构经历着革命式变迁。\n⑤有学者提出，两代人的居住格局应保持“一碗汤的距离”，既要让子代和父代有各自的独立空间，又要维系家庭成员之间的亲密关系。\n⑥不同价值观念和行为方式在同一时空并存的环境下，代际之间的适度空间和社会距离是彼此有效沟通与和谐共处的基本条件之一。\n将以上6个句子重新排列，语序正确的一项是：",
   "options": [
    "A. ⑤①③④②⑥",
    "B. ②⑥③④①⑤",
    "C. ④②⑥③⑤①",
    "D. ⑥③⑤④①②"
   ],
