   "module": "言语理解与表达",
   "source": "2021年天津市公务员考试《行测》题 · 第1题",
   "question": "无论是体长、体重或是综合进行考量，蓝鲸都无愧于现存最“大”的生物体。而生活在广袤的大洋中，蓝鲸不需要像陆生动物那样费力地支撑起自己沉重的身躯，可以自在地        。\n填入划横线部分最恰当的一项是：",
