   "source": "2022年天津市公务员录用考试《行测》试题 · 第2题",
   "question": "共青团紧扣党在不同历史时期的中心任务，团结带领广大团员青年积极投身人民群众的壮阔实践，在民族复兴征程上勇当先锋、倾情奉献，发挥生力军和突击队作用，使实现民族复兴成为中国青年运动            的恢弘主流。\n填入划横线部分最恰当的一项是：",
