   "module": "言语理解与表达",
   "source": "2022年天津市公务员录用考试《行测》试题 · 第13题",
   "question": "慈善是一个历史变动中的概念，所含内容在不同历史时期并不完全一致。譬如古代慈善事业多系直接性物质救济，呈现出重养轻教的特征。但近代以来，愈发重视慈善教育的功能，强调教养并重。当代中国慈善事业更是朝着社会公益服务的多元化方向发展。但是，不管如何变化，慈善的根本内涵没有改变，即民间社会各界秉持人道善心，救助、关怀社会弱势群体与困难群众，这也是慈善本义内容所在。至于慈善的外延表现，则会随着时代的变化而变化，譬如慈善动机、慈善形式、慈善流程等。我们在讨论慈善概念的时候，应该对其内涵与外延予以区分，在此基础上考察慈善发展的历史。\n这段文字意在说明：",
   "options": [
    "A. 公益服务慈善的核心要义",
    "B. 教养并重是当代慈善的主要特点",
    "C. 慈善的社会教育功能越来越受到重视",
    "D. 慈善的内涵并不随外延的变化而变化"
   ],
   "answer": "D",
   "analysis": "文段首先引出“慈善”的话题，表明慈善在不同历史时期概念并不完全一致，接着通过“譬如”举例论证。然后通过转折关联词“但是”强调慈善的内涵没有改变。后文通过慈善的外延会随着时代的变化而变化，且在探讨慈善概念时，应对内涵与外延予以区分，来进一步论证慈善的内涵不会随着变化而变化，故文段强调慈善内涵并不改变，对应D项。\nA项，“公益服务”对应转折之前的内容，非重点，且“核心要义”表述不明确，排除；\nB项“教养并重”及C项“慈善的社会教育功能”均为文段例子部分的内容，非重点，排除。\n故正确答案为D。\n【文段出处】光明网《内涵与外延：慈善概念再思考》",
   "exam": "tianjin",
