   "source": "2022年天津市公务员录用考试《行测》试题 · 第15题",
   "question": "青藏高原是除南北极以外冰雪储量最大的地区，是亚洲十多条大江大河的发源地，被称为“亚洲水塔”。过去50年，青藏高原及其相邻地区的冰川面积由5.3万平方公里缩减至4.5万平方公里；青藏高原大于1平方公里的湖泊数量从1081个增加到1236个，湖泊面积从4万平方公里增加到近5万平方公里；受冰川融水径流量增长影响，雅鲁藏布江、印度河上游年径流量呈增加趋势。随之而来的将是灾害风险的加剧。专家表示，全球变暖是大趋势，我们能做一些“减缓”工作，但“适应”始终是核心，这就需要建立相应的预警体系，把损失降到最低。\n这段文字意在说明：",
   "options": [
    "A. 亚洲水塔的生态环境岌岌可危",
    "B. 全球变暖加剧了亚洲水塔的生态危机",
    "C. 建立亚洲水塔灾害监测预警体系势在必行",
    "D. 亚洲水塔变化影响着大批人的生存和发展"
   ],
   "answer": "C",
   "analysis": "文段首先指出青藏高原被称为“亚洲水塔”，随后通过数据资料详细介绍了过去50年该地区的冰川面积、湖泊数量、湖泊面积以及雅鲁藏布江、印度河上游年径流量的变化情况，紧接着提出问题，即青藏高原的这一系列变化加剧了灾害风险，最后通过转折词“但”引出文段重点，并通过“需要”提出对策，要在青藏高原地区建立相应的预警体系，对应C项。\nA项，“生态环境岌岌可危”文段并未提及，无中生有，排除；\nB项，“全球变暖”属于转折前的部分内容，非重点，排除；\nD项，“影响着大批人的生存和发展”文段并未提及，无中生有，排除。\n故正确答案为C。\n【文段出处】科技日报《亚洲水塔全球最脆弱 我国建立灾害监测预警体系》",
   "exam": "tianjin",
