   "module": "言语理解与表达",
   "source": "2022年天津市公务员录用考试《行测》试题 · 第16题",
   "question": "碳酸铅为无机化合物，它以白铅矿的形式存在于自然界中。像碳酸铅这样的无机样本很难直接进行年代测定。这是因为，自然界中的碳元素主要有3种同位素，其中碳14为天然放射性同位素，碳测年法就是利用生物体死亡后体内碳14含量随时间减少的规律进行年代测定的技术，主要用于测定生物物质，例如动植物遗骸，也可以测定藏品中木器、竹器、牙骨器、纸张、纺织物等含碳有机物的年代。虽然碳酸铅含有放射性碳，可惜长期以来，科学家一直没能找到直接测定碳酸铅年代的方法。\n接下来最可能说的是：",
   "options": [
    "A. 测定碳酸铅年代的新方法",
    "B. 碳测年法的优势和弊端",
    "C. 碳酸铅和考古的关系",
    "D. 碳测年法的技术原理"
   ],
   "answer": "A",
   "analysis": "文段开篇指出碳酸铅为无机化合物，很难直接进行年代测定，随后分析原因：碳测年法是利用生物体死亡后体内碳14含量随时间减少的规律进行测年，其主要应用领域是测定生物物质或一些含碳有机物的年代。由此可见，碳酸铅作为无机化合物不在其适用范围内。尾句指出，科学家一直没有找到直接测定碳酸铅年代的方法。故后文应继续围绕“测定碳酸铅年代的方法”这一话题展开论述，对应A项。\nB项，“碳测年法”偏离文段核心话题，文段围绕“碳酸铅的年代测定”展开论述，与文段衔接不当，排除；\nC项，文段未提及“碳酸铅和考古的关系”的相关话题，无中生有，排除；\nD项，“技术原理”文段中已详细论述过，后文不会再论述，且偏离文段核心话题，排除。\n故正确答案为A。\n【文段出处】科技日报《确定远古物品年龄有新方法——白色颜料所含碳酸铅年代可直接测定》",
   "exam": "tianjin",
   "year": 2022
