   "question": "领导干部特别是高级干部担负着推进改革的重要职责。要增强政治责任感、历史使命感，以攻坚克难、迎难而上的政治勇气，直面矛盾问题不        ，铲除顽瘴痼疾不        ，应对风险挑战不        ，奋力打开改革发展新天地。\n依次填入画横线部分最恰当的一项是：",
