   "question": "医疗领域是高度数字化的。整个诊疗过程都留有痕迹，且不同环节前后印证、            。换言之，无中生有、            必然会被记录在案，会留下蛛丝马迹。在整治骗保上，不妨聚焦虚假住院、药品倒卖等突出问题，开发更多大数据筛查模型，让骗保行为逃不过技术的            。\n依次填入画横线部分最恰当的一项是：",
