   "question": "我国新的职业教育法对职业教育的新定位是类型教育。把职业教育办为与普通教育平等的类型教育，是解决教育“分层”问题的重点与难点。当前，我国对职业教育的投入，还没有做到与普通教育一致，而从办好职业教育所需师资、实习实训场地、产教融合教育测算，职业教育所需经费投入是普通教育所需经费投入的3倍。显然，要让地方政府拿出举办普高3倍的经费办职业学校，这不但涉及增加教育经费投入，而且也将是重大的教育政绩观转变。\n这段文字意在说明：",
