   "source": "2025年天津市公务员录用考试《行测》题 · 第18题",
   "question": "非遗要“火起来”，更要扩大市场，去积极拥抱新技术，焕发新的生机。我们看到随着新技术同非遗的有机结合，非遗的传播彻底突破了地域限制，借助互联网+、VR等全新的打开方式，非遗IP在青年人群体中间成为时尚。例如，某武侠游戏联合“天下第一苗寨”西江千户苗寨及3位苗族代表性非遗传承人深度合作，在剧情、建筑、服饰中加入苗族文化元素，让更多年轻人对非遗产生探究的兴趣。而来自中国古老的文化精粹，也在走入寻常百姓家的同时，以数字时代的方式潜移默化地传承下去。\n这段文字意在说明：",
