   "source": "2025年天津市公务员录用考试《行测》题 · 第20题",
   "question": "在动物王国中，毒蜘蛛黑寡妇的毒液令人闻风丧胆。这种毒液由七种不同毒素组成，其中大多数毒素的目标是昆虫和甲壳类动物的神经系统。但有一种特别的成分：img/formula-6e27632bdd146bdd.webp-蛛毒素，却对脊椎动物有着致命杀伤力，尤其对人类构成威胁。当img/formula-6e27632bdd146bdd.webp-蛛毒素找到它的目标——神经细胞间突触时，就像一把精密的钥匙找到了锁眼。它与突触上的特定受体结合，就像打开了潘多拉魔盒，导致钙离子如潮水般涌入。这一过程引发了神经递质的过度释放，导致剧烈的肌肉收缩和痉挛，身体内部仿佛上演了一场失控的舞蹈。\n关于img/formula-6e27632bdd146bdd.webp-蛛毒素，上文提到了：",
