   "question": "灵动活泼的方言往往成为点睛之笔。鲁迅的作品中不乏源自绍兴方言的重叠词“白历历”“寒颤颤”，事物性状模态            。周立波在《山乡巨变》中写道：“她的脚力有些来不及，鞋子流水踢着路上的石头”，用了湖南益阳方言“流水”，表示“经常地、不间断地”，简练准确而            。\n依次填入画横线部分最恰当的一项是：",
