   "question": "彗星曾是不祥的象征。它们突兀地“闯入”人类的夜空记忆，带着长尾与光辉，也裹挟着瘟疫与战火的        。可在现代科学的叙述里，彗星慢慢露出“时间胶囊”的真实面目：它们在太阳系寒冷的边陲缓慢生长，把45亿年前的物质配方小心        。每一次近日点的“炙烤”像一次        的拆封，让我们得以窥见远古的物质。\n依次填入画横线部分最恰当的一项是：",
