   "question": "。近年来，监管部门坚持“零容忍”，对违规炒股的打击追溯历史更久、追责处罚更严。未来应继续保持高压态势，一方面充分利用大数据、人工智能等科技手段炼就火眼金睛，提升精准发现能力，让隐蔽违规交易无所遁形。另一方面要抽丝剥茧、一追到底，重点关注违规炒股的背后是否存在内幕交易、市场操纵等行为，一旦发现涉嫌犯罪的，应移尽移、当捕则捕、该诉则诉，以严惩重罚使从业者心生畏惧，不敢越雷池半步。\n填入画横线部分最恰当的一项是：",
