   "question": "文物普查既需要专业文保队伍的辛勤付出，也离不开公众参与、社会投入，文物保护的意识就在这个过程中不断生长。回顾历次文物普查，“二普”将文物分类中的“革命遗址及革命纪念建筑物”扩展为“近现代重要史迹及代表性建筑”；“三普”将工业遗产、乡土建筑等类型纳入普查范围；多地在“四普”实践中首次明确将文化景观纳入普查对象。文物认定标准不断完善，文物保护对象不断扩展，文物价值内涵不断丰富，将进一步强化历史文化遗产保护、提升全民文物保护行动力。\n这段文字意在说明：",
