   "question": "铜车马在塑形方面使用了圆雕、錾刻、磋磨等。在铸造方法上，根据构件的大小、薄厚以及不同的形状，使用了多范合铸、包铸等多种方法。如大径178厘米，小径129厘米的椭圆形车盖，厚度仅0.1~0.4厘米，整体用浑铸法一次铸出，先将车盖浇铸成形，再经加热锻打成形。即使在今天，要铸成这么大而薄、均匀呈穹隆形的铜件也非易事。大型厚壁或长杆型铸件，则采用空心铸造，既减轻了重量，也节省大量金属，还避免了铸件疏松、受热产生裂纹等缺陷。一些复杂构件则分解成简单的构件分别铸造，再合成一个完整的构件，这是秦代工艺的一大创新。\n这段文字主要介绍了秦代铜车马：",
