   "question": "与苔草等植物相比，泥炭藓能分泌大量酸性抑菌的次级代谢产物。泥炭藓湿地中，人为排水活动导致富含抑菌酚类代谢产物的泥炭藓被草本植物所取代，植物抑菌代谢产物减少，进而增强了合成酚氧化酶的微生物活性，提高了土壤酚氧化酶活性，导致泥炭藓湿地有机碳降解增速，土壤碳含量在排水后迅速下降。相反，在非泥炭藓湿地如苔草湿地中，草本植物为了应对长期排水导致的干旱及啃食胁迫，合成了更多次级代谢产物，降低了合成酚氧化酶的微生物活性，进而导致酚氧化酶活性下降，土壤碳库表现得更“顽强”。\n这段文字没有解释下列哪一问题？",
