   "question": "人工智能属于数据科学。相较于实验科学、理论科学、计算科学，数据科学强调利用仪器收集或仿真计算产生的大量数据进行分析与知识提取，更加突出数据在发现规律和形成理论中的作用。实际上，自动驾驶、可穿戴设备、智能机器人等都具有典型的数据密集型特征。因此，应进一步支持建设人工智能领域基础数据库和专题数据库，扩大面向人工智能应用的公共数据供给范围，鼓励引导相关主体开展高质量数据的采集、存储、交易及其与人工智能技术的协同研发，服务算法设计、模型训练、产品验证、场景应用等实际需求。\n这段文字意在说明：",
