   "source": "2026年天津市公务员录用考试《行测》题 · 第20题",
   "question": "纵观当下较为热门的人工智能创作软件，大多都可通过文字描述直接生成简短影像。人工智能的“生成”比计算机的“渲染”有了更大的主动性，但也引发了诸多技术伦理问题。例如，人工智能生成的影像内容可能会在不经意间侵犯版权；过度依赖人工智能生成技术，可能导致创作者的原创能力和艺术审美逐渐退化，使作品丧失情感温度。面对这些问题，艺术家们积极做出回应，尝试通过不同的路径与人工智能展开深度合作，探索更具人文内涵的生成式动画创作。\n这段文字接下来最可能讲的是：",
