   "analysis": "文段开篇指出中华民族自古秉持“天下大同”等理念，认为大一统是顺理成章的，接着指出自秦统一中国后，所有入主中原的民族都秉持大一统的共同信念，最后强调我们统一的多民族国家由各民族共同缔造，也需各民族共同维护、巩固和发展。故文段重点介绍我国各民族秉持着大一统的共同信念，对应D项。\nA项“情感相亲”、B项“经济相依”文段均未提及，无中生有，排除；\nC项“文化相通”仅对应“文明不可断”这一方面，表述片面，排除。\n故正确答案为D。\n【文段出处】国务院公报《在全国民族团结进步表彰大会上的讲话》",
